<script lang="ts">
 import type {Project} from './model';import {translator} from './i18n';import {markedRecords,markedDeletionPlan,purgeMarkedRecords} from './marked-records';import {catalogs} from './desktop-menu';import {ask} from './storage';import {Search,Trash2,RefreshCw} from '@lucide/svelte';
 export let project:Project;export let onapply:(p:Project)=>void;let selected:string[]=[],checked=false,error='';$:t=translator(project.settings.language);$:records=markedRecords(project);$:plan=checked?markedDeletionPlan(project,selected):[];
 async function remove(){try{if(!(await ask(t('Удалить выбранные помеченные записи без возможности восстановления? Сначала сохраните резервную копию.','Ștergeți definitiv înregistrările marcate selectate? Salvați mai întâi o copie de siguranță.'))))return;onapply(purgeMarkedRecords(project,selected));selected=[];checked=false;error='';}catch(e){error=String(e);}}
</script>
<div class="marked-deletion"><div class="toolbar"><button class="button secondary" onclick={()=>{checked=true;error='';}} disabled={!selected.length}><Search size={16}/>{t('Проверить ссылки','Verifică referințele')}</button><button class="button secondary" disabled={!checked||!selected.length||plan.some(r=>r.references.length)} onclick={remove}><Trash2 size={16}/>{t('Удалить','Șterge')}</button><button class="icon-button" aria-label={t('Обновить','Actualizează')} onclick={()=>{checked=false;selected=[];}}><RefreshCw size={16}/></button></div><p>{t('Удаляются только явно помеченные записи и черновики документов. Архивные записи не считаются помеченными. Записи со ссылками остаются в базе.','Se șterg doar înregistrările și ciornele marcate explicit. Înregistrările arhivate nu sunt marcate automat. Înregistrările referite rămân în bază.')}</p>{#if error}<p role="alert">{error}</p>{/if}<table><thead><tr><th></th><th>{t('Справочник','Catalog')}</th><th>{t('Наименование','Denumire')}</th><th>{t('Проверка','Verificare')}</th></tr></thead><tbody>{#each records as record}{@const key=record.kind+':'+record.id}{@const result=plan.find(r=>r.kind===record.kind&&r.id===record.id)}<tr class:attention-row={!!result?.references.length}><td><input type="checkbox" aria-label={record.name} checked={selected.includes(key)} onchange={e=>{selected=e.currentTarget.checked?[...selected,key]:selected.filter(id=>id!==key);checked=false;}}/></td><td>{record.kind==='payment-batches'?t('Групповой ввод оплаты','Plăți în grup'):catalogs.find(c=>c.id===record.kind)?.[project.settings.language]||record.kind}</td><td>{record.name}</td><td>{result?(result.references.length?t('Есть ссылки — удаление запрещено','Există referințe — ștergere blocată'):t('Ссылок нет','Fără referințe')):'—'}</td></tr>{/each}</tbody></table>{#if !records.length}<p>{t('Помеченных записей нет.','Nu există înregistrări marcate.')}</p>{/if}</div>
<style>.marked-deletion{display:flex;flex-direction:column;gap:14px;padding:16px}.toolbar{display:flex;gap:8px;align-items:center}table{width:100%;border-collapse:collapse}th{text-align:left;background:#80808020}th,td{padding:8px}</style>
